clients_db=# -- Q1: does system-stats still exist in page_components right now?
SELECT position, slot_name, length(rendered_html) AS html_len, updated_at
FROM page_components
WHERE page_id = '6e988cc4-4898-4021-aa5e-2ab0271f9b75'
ORDER BY position;

-- Q2: if it IS still there, compute visible length the way the assembler does
--     (strip style/script/tags/entities/whitespace) — ≤10 means the filter dropped it
SELECT position, slot_name,
       length(rendered_html) AS html_len,
       length(
               regexp_replace(
                       regexp_replace(
                               regexp_replace(
                                       regexp_replace(
                                               regexp_replace(rendered_html, '<style[^>]*>.*?</style>', '', 'gi'),
                                               '<script[^>]*>.*?</script>', '', 'gi'),
                                       '<[^>]+>', '', 'g'),
                               '&[a-zA-Z#0-9]+;', '', 'g'),
                       '\s+', '', 'g')
       ) AS approx_visible_len
FROM page_components
WHERE page_id = '6e988cc4-4898-4021-aa5e-2ab0271f9b75'
ORDER BY position;
