4e2d8e8e-47a7-476a-95ca-8d71f32e894a|site-adoption-agent|Site Adoption Agent|Crawls an existing site, analyses structure and content, creates specs and work items to recreate it|code-driven|{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["site_record", "formatted_crawl", "adoption_analysis", "adoption_result", "design_fingerprint", "design_intent_generated"]}, "description": "Adoption plan applied — dispatch loop will process work items"}, "apply_plan": {"action": "apply_adoption_plan", "config": {"domain": "site_record.domain", "site_id": "site_record.site_id", "input_fields": ["site_record", "crawl_result", "adoption_analysis", "content_direction_analysis"], "adoption_plan": "adoption_analysis", "source_url_field": "input_data.target_url"}, "next_step": "populate_nav", "description": "Write specs, create pages, create work items from analysis", "output_field": "adoption_result"}, "crawl_site": {"action": "firecrawl_crawl", "config": {"url_field": "input_data.target_url", "scrape_config": {"limit": 30, "formats": ["markdown", "rawHtml"], "max_age": 600000, "only_main_content": false, "max_discovery_depth": 4}}, "next_step": "format_crawl", "description": "Crawl the existing site via webscrape adapter", "output_field": "crawl_result"}, "analyze_site": {"action": "execute_llm_prompt", "config": {"model": "claude-sonnet-4-6", "ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "max_tokens": 32000, "temperature": 0.2, "input_fields": ["site_record", "formatted_crawl", "input_data"], "output_format": "json", "prompt_template": "You are analysing a crawled website to plan its adoption into our website building system.\n\nDomain: {{.site_record.domain}}\n\nCrawled page summaries:\n{{.formatted_crawl.research_text}}\n\nAnalyse this site and produce a JSON object. Respond ONLY with valid JSON, no markdown backticks.\n\n{\n  \"identity\": {\n    \"company_name\": \"extracted company/brand name\",\n    \"tagline\": \"extracted tagline or slogan\",\n    \"industry\": \"detected industry vertical\",\n    \"target_audience\": \"who the site serves\",\n    \"tone\": \"writing tone description\",\n    \"services\": [{\"name\": \"...\", \"description\": \"...\"}]\n  },\n  \"design\": {\n    \"palette\": {\"primary\": \"#hex or description\", \"secondary\": \"#hex or description\", \"accent\": \"#hex or description\", \"background\": \"#hex or description\", \"text\": \"#hex or description\"},\n    \"typography\": {\"heading_font\": \"font name\", \"body_font\": \"font name\"},\n    \"visual_tone\": \"visual style description\"\n  },\n  \"pages\": [\n    {\n      \"name\": \"kebab-case-name\",\n      \"title\": \"Page Title\",\n      \"url\": \"/path/to/page.html\",\n      \"page_type\": \"content|tool|game|guide|section-index|blog-index|blog-post|landing\",\n      \"in_header\": true,\n      \"in_footer\": true,\n      \"nav_label\": \"Nav Label\",\n      \"meta_description\": \"page description\",\n      \"sections\": [\"hero\", \"features\", \"call-to-action\"]\n    }\n  ],\n  \"interactive_features\": [\n    {\"name\": \"feature\", \"type\": \"calculator|search|form|tool|game|simulation\", \"description\": \"what it does\", \"self_contained\": true, \"page\": \"page-name\"}\n  ]\n}\n\nRules:\n- Page names must be kebab-case (index for homepage)\n- Use standard section names: hero, features, call-to-action, generic-text-block, testimonials, pricing, faq, contact-form, guide-list, tool-list, game-list\n- Do NOT include existing_content — content extraction is handled separately\n- Identify interactive features (calculators, search, games, simulations) separately\n- Include every distinct page in the crawl, skipping only 404 pages or true duplicates. Interactive pages (tools, games, simulators) MUST be included even if their textual content is minimal — the interactive surface itself is the content and downstream processes will analyse it.\n- page_type guidance:\n  - \"tool\": individual calculator, converter, or analyser page (input -> output, deterministic). One page per tool.\n  - \"game\": individual playable prototype, simulator, or interactive demo where the user takes ongoing action (clicks, drags, runs simulations). One page per game/prototype. Use this even if the page also has explanatory prose.\n  - \"blog-post\": individual news item, opinion piece, or time-bound article with primarily prose content. Use the guide page_type (not blog-post) for instructional how-to, tutorial, or explainer pages that teach the reader to do or understand something; one page per guide.\n  - \"blog-index\": a listing page enumerating blog-posts (e.g. /guides/index.html).\n  - \"section-index\": a section landing/hub page that lists the child tool or game pages within a section (e.g. /tools/index.html, /games/index.html). Use this for the directory page of a tools or games section.\n  - \"content\": general-purpose informational page (about, contact, terms).\n  - \"landing\": the site homepage (kebab name \"index\") OR a marketing-focused entry page.\n- Distinguish directory/section-index pages from item pages: /games/index.html -> \"section-index\" (it lists prototypes); /games/auto-battler/ -> \"game\" (it IS a prototype).\n- Omit interactive_features if none exist"}, "next_step": "classify_archetype", "description": "LLM analyses crawled content — extracts identity, design, pages, sections", "output_field": "adoption_analysis"}, "crawl_failed": {"action": "complete_workflow", "config": {"error": "Site crawl failed or returned no usable content", "status": "failed"}, "description": "Fail if crawl produced nothing"}, "format_crawl": {"action": "format_crawl_for_analysis", "config": {"crawl_field": "crawl_result", "summary_chars_per_page": 350}, "next_step": "check_crawl_content", "description": "Format crawl pages into readable text for LLM analysis", "output_field": "formatted_crawl"}, "populate_nav": {"action": "populate_nav_tables", "config": {"site_id": "site_record.site_id", "error_step": "generate_design_intent", "max_header_items": 8}, "next_step": "generate_design_intent", "description": "Rebuild nav tables from adopted pages (delete-and-insert, clears stale entries)", "output_field": "nav_data"}, "select_content": {"action": "select_representative_content", "config": {"max_pages": 3, "max_total_chars": 15000}, "next_step": "derive_content_direction", "error_step": "apply_plan", "description": "Select 2-3 prose-heavy pages from crawl for writing style analysis", "output_field": "representative_content"}, "fetch_primary_css": {"action": "firecrawl_scrape", "config": {"url_field": "design_fingerprint.primary_css_url", "error_step": "analyze_site", "scrape_config": {"formats": ["rawHtml"], "only_main_content": false}}, "next_step": "enrich_fingerprint", "description": "Fetch primary external CSS file via webscrape adapter", "output_field": "css_scrape_result"}, "classify_archetype": {"action": "execute_llm_prompt", "config": {"model": "claude-sonnet-4-6", "ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "max_tokens": 4000, "temperature": 0.2, "input_fields": ["site_record", "formatted_crawl", "adoption_analysis"], "system_prompt": "You are analyzing a website to produce a site archetype classification. Your job is to describe what this site IS — not what it should become. This is a snapshot, not an aspiration. Think about what you would tell someone who asked \"what kind of site is this?\" after you spent 5 minutes looking at it.", "prompt_template": "Domain: {{.site_record.domain}}\n\n== CRAWL DATA ==\n\n{{.formatted_crawl.research_text}}\n\n== STRUCTURAL ANALYSIS (from previous step) ==\n\n{{.adoption_analysis}}\n\n== INSTRUCTIONS ==\n\nProduce a JSON object classifying this site. Every field is required. Be specific and honest — \"none\" is a valid answer. Do not invent features that are not in the crawl.\n\n{\n  \"label\": \"A 2-4 word human-readable classification (e.g. developer utility platform, industrial product showcase, vertical listing aggregator, content marketing hub)\",\n  \"industry\": \"the industry or vertical this site serves\",\n\n  \"character\": {\n    \"feel\": \"3-5 descriptive words for the overall impression\",\n    \"polish\": \"how finished does it look — rough/moderate/polished, with a brief note on why\",\n    \"budget_impression\": \"what budget level does it suggest — indie/small business/mid-market/enterprise\",\n    \"age_impression\": \"does it feel new or established — and what gives that impression\",\n    \"commercial_intent\": \"how is it trying to make money, or is it not — describe what you see\",\n    \"density\": \"how much content per screen — sparse/low/medium/high/dense\"\n  },\n\n  \"design\": {\n    \"palette_mood\": \"describe the colour approach — dark/light, accent colours, warmth/coolness\",\n    \"layout_approach\": \"what layout patterns dominate — grids, cards, sidebars, full-width, split panels\",\n    \"typography_feel\": \"what do the fonts suggest — corporate, technical, playful, editorial\",\n    \"imagery\": \"what visual assets are used — photos, illustrations, icons, none, screenshots, charts\",\n    \"animation\": \"how much motion — none, hover states, transitions, full animation\",\n    \"responsive\": \"does the crawl suggest mobile support — and how\"\n  },\n\n  \"content\": {\n    \"primary_type\": \"what is the main content — prose, products, tools, media, listings, data\",\n    \"secondary_type\": \"what else is there, if anything\",\n    \"voice\": \"how does the site talk — formal, casual, technical, sales-oriented, educational\",\n    \"media\": \"what media types are present — text only, images, video, audio, interactive elements\"\n  },\n\n  \"purpose\": [\"array of what the site exists to do\"],\n  \"content_model\": [\"array of content types present\"],\n  \"interaction_patterns\": [\"array of what users DO on this site\"],\n  \"revenue_model\": \"none | advertising | affiliate | e-commerce | subscription | lead-generation | freemium | mixed (describe)\",\n  \"visual_character\": [\"array of style tags\"],\n  \"audience\": [\"array of who this is for\"],\n\n  \"structure\": {\n    \"index_layout\": \"what the homepage looks like\",\n    \"listing_style\": \"how collections of items are presented\",\n    \"navigation\": \"how users move around\",\n    \"page_depth\": \"how many clicks to real content — shallow (1-2), medium (2-3), deep (3+)\"\n  },\n\n  \"constraints\": [\"array of things the improvement loop should NEVER do to this site — inferred from what the site is\"]\n}\n\nRespond with ONLY the JSON object. No explanation, no markdown backticks."}, "next_step": "select_content", "description": "LLM classifies site archetype — character, design patterns, purpose, constraints", "output_field": "site_archetype_analysis"}, "enrich_fingerprint": {"action": "enrich_fingerprint_with_css", "config": {"css_scrape_field": "css_scrape_result", "fingerprint_field": "design_fingerprint"}, "next_step": "analyze_site", "error_step": "analyze_site", "description": "Parse fetched CSS and merge into design fingerprint (fonts, variables, colours)", "output_field": "design_fingerprint"}, "ensure_site_record": {"action": "ensure_site_record", "config": {"input_fields": ["site_id", "domain"], "domain_override_field": "input_data.destination_domain"}, "next_step": "crawl_site", "description": "Create or load site record for the domain", "output_field": "site_record"}, "check_crawl_content": {"action": "conditional", "config": {"condition": "formatted_crawl.content_quality != none", "else_step": "crawl_failed", "then_step": "extract_fingerprint"}, "description": "Check if the crawl returned usable content"}, "extract_fingerprint": {"action": "extract_design_fingerprint", "config": {"crawl_field": "crawl_result"}, "next_step": "extract_interactive_fingerprint", "description": "Extract concrete design data (colours, fonts, layout) from crawled HTML — no LLM", "output_field": "design_fingerprint"}, "write_design_intent": {"action": "write_site_spec", "config": {"aspect": "design_intent", "source": "site-adoption-agent", "site_id": "site_record.site_id", "spec_data": "design_intent_generated.result", "source_agent": "site-adoption-agent"}, "next_step": "complete", "error_step": "complete", "description": "Write design_intent spec from LLM-generated design brief", "output_field": "design_intent_written"}, "check_has_external_css": {"action": "conditional", "config": {"condition": "design_fingerprint.has_external_css == true", "else_step": "analyze_site", "then_step": "fetch_primary_css"}, "description": "Check if fingerprint found external CSS files to fetch"}, "generate_design_intent": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "max_tokens": 4000, "temperature": 0.3, "input_fields": ["site_record", "design_fingerprint", "adoption_analysis"], "prompt_template": "You are a senior brand designer writing a design brief for a web designer. You have concrete CSS data extracted from an existing site and you need to describe what the design IS — its character, its intent, its visual personality — so that a designer can reproduce and eventually evolve it.\n\nDomain: {{if .site_record}}{{.site_record.domain}}{{end}}\n\n== EXTRACTED DESIGN DATA ==\n{{if .design_fingerprint}}{{if .design_fingerprint.suggested_mapping}}Suggested CSS mapping:\n{{range $key, $value := .design_fingerprint.suggested_mapping}}  {{$key}}: {{$value}}\n{{end}}{{end}}\n{{if .design_fingerprint.css_variables}}Original CSS variables:\n{{range $key, $value := .design_fingerprint.css_variables}}  {{$key}}: {{$value}}\n{{end}}{{end}}\n{{if .design_fingerprint.typography}}Typography:\n{{range $key, $value := .design_fingerprint.typography}}  {{$key}}: {{$value}}\n{{end}}{{end}}\n{{if .design_fingerprint.dark_sections}}Dark sections: predominant scheme is {{.design_fingerprint.dark_sections.predominant_scheme}}{{end}}{{end}}\n\n== SITE IDENTITY (from LLM analysis) ==\n{{.adoption_analysis}}\n\nProduce a design intent specification that describes the character of this design — not just the values, but WHY those values work and what they achieve. A designer reading this should understand the visual personality well enough to make good decisions about things not explicitly specified.\n\nRespond with ONLY valid JSON:\n{\n  \"source\": \"design_reference\",\n  \"palette\": {\n    \"character\": \"A detailed description of the colour approach — what mood it creates, what it communicates about the brand, why these specific colours work for this industry and audience\",\n    \"reference_values\": {\n      \"primary\": \"#hex from the extracted data\",\n      \"secondary\": \"#hex\",\n      \"accent\": \"#hex\",\n      \"background\": \"#hex\",\n      \"surface\": \"#hex\",\n      \"text\": \"#hex\",\n      \"text_muted\": \"#hex\"\n    },\n    \"guidance\": \"What to preserve about the palette and what constraints to respect when evolving it\"\n  },\n  \"typography\": {\n    \"character\": \"A description of what the font choices communicate — why these fonts suit this type of site and audience\",\n    \"reference_values\": {\n      \"font_family\": \"the extracted font stack\",\n      \"heading_font\": \"heading font if different\"\n    },\n    \"guidance\": \"What to preserve about the typography when evolving\"\n  },\n  \"spacing\": {\n    \"character\": \"A description of the spacing approach — dense or spacious, why that suits the content type\",\n    \"reference_values\": {\n      \"section_padding\": \"extracted or inferred\",\n      \"container_max_width\": \"extracted or inferred\"\n    }\n  },\n  \"dark_light\": {\n    \"scheme\": \"dark|light|mixed\",\n    \"rationale\": \"Why this scheme works for this site\"\n  },\n  \"overall_character\": \"A 2-3 sentence summary of the entire visual identity that captures its essence\"\n}\n\nRules:\n- The reference_values MUST come from the extracted design data above, not invented\n- The character descriptions should explain WHY the values work, not just restate them\n- The guidance fields should help a designer know what to preserve vs what can evolve\n- If extracted data is missing for a field, use a reasonable inference and note it"}, "next_step": "write_design_intent", "error_step": "complete", "description": "LLM generates rich semantic design_intent from extracted fingerprint data", "output_field": "design_intent_generated"}, "derive_content_direction": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "api_key_env_var": "ANTHROPIC_API_KEY"}, "max_tokens": 6000, "temperature": 0.2, "input_fields": ["site_record", "representative_content", "adoption_analysis"], "prompt_template": "You are a senior copywriter and brand strategist. You are analysing the actual content from a website to produce a detailed writing style guide that another writer could follow to recreate content in exactly the same voice, tone, and style.\n\nDomain: {{if .site_record}}{{.site_record.domain}}{{end}}\n\nHere is the actual content from representative pages on this site:\n\n{{if .representative_content}}{{.representative_content.selected_text}}{{end}}\n\nStudy this content carefully and deeply. Pay attention to:\n- How headings are phrased (questions? statements? commands? how long?)\n- Sentence length, rhythm, and construction patterns\n- Level of formality vs conversational tone\n- How technical terms are handled (defined? assumed known? avoided? explained inline?)\n- Use of first/second/third person and when each is used\n- How confidence and authority are expressed without overstepping\n- What the content deliberately avoids saying (no promises? no superlatives? no jargon without explanation?)\n- How calls-to-action are worded (hard sell? soft? informational? what verbs?)\n- Any legal, regulatory, or compliance patterns (disclaimers, caveats, qualifications)\n- Use of examples, analogies, worked calculations, or concrete illustrations\n- How lists, steps, and structured content are formatted\n- The emotional register (reassuring? challenging? neutral? playful? dry?)\n- How the site builds trust (through expertise? through transparency? through relatability?)\n- What assumptions the site makes about what the reader already knows\n- How deeply the content explores each topic (surface overview? deep dive? practical application?)\n- How bold, italics, links, and other formatting are used\n- How sections transition from one idea to the next\n\nProduce a JSON writing style guide. Be as specific and detailed as possible — a writer reading this guide should be able to perfectly match the voice without ever seeing the original site. Respond ONLY with valid JSON, no markdown backticks.\n\n{\n  \"voice\": {\n    \"register\": \"Describe the overall register in one detailed sentence\",\n    \"person\": \"Which grammatical person is used and when\",\n    \"authority_level\": \"How the site establishes authority and credibility\",\n    \"emotional_tone\": \"The emotional quality and how it makes the reader feel\",\n    \"formality\": \"Where it sits on formal-casual spectrum with specific markers\"\n  },\n  \"sentence_style\": {\n    \"average_length\": \"Short/medium/long and typical word count per sentence\",\n    \"structure_patterns\": \"How sentences are typically constructed\",\n    \"rhythm\": \"The cadence of the writing\",\n    \"connectives\": \"How ideas are linked between sentences and paragraphs\"\n  },\n  \"persuasion_approach\": {\n    \"method\": \"How the site convinces without selling\",\n    \"trust_building\": \"How trust is established\",\n    \"social_proof_style\": \"How social proof is handled\"\n  },\n  \"content_depth\": {\n    \"thoroughness\": \"How deeply topics are explored\",\n    \"assumed_knowledge\": \"What the reader is expected to already know\",\n    \"explanation_pattern\": \"How complex ideas are introduced and explained\"\n  },\n  \"writing_rules\": [\n    \"Each rule should be specific and actionable, not vague.\",\n    \"Extract at least 10-15 rules from actual patterns in the content.\",\n    \"Example: 'Technical terms must be explained in plain English on first use'\",\n    \"Example: 'Paragraphs are 2-3 sentences maximum. One idea per paragraph.'\"\n  ],\n  \"compliance_rules\": [\n    \"Any legal, regulatory, financial, medical, or professional compliance patterns observed\",\n    \"Return empty array [] if no compliance patterns are evident\"\n  ],\n  \"heading_style\": {\n    \"format\": \"How headings are typically phrased\",\n    \"hierarchy\": \"How heading levels are used\",\n    \"examples_from_site\": [\"Copy 3-4 actual headings from the content\"]\n  },\n  \"paragraph_style\": {\n    \"typical_length\": \"How long paragraphs typically are\",\n    \"structure\": \"How paragraphs are internally organised\",\n    \"opening_patterns\": \"How paragraphs typically begin\"\n  },\n  \"cta_style\": {\n    \"approach\": \"How calls-to-action are handled\",\n    \"verb_choices\": \"What action verbs are used\",\n    \"examples_from_site\": [\"Copy 3-4 actual CTAs from the content\"]\n  },\n  \"terminology\": {\n    \"approach\": \"How domain-specific terms are handled\",\n    \"definition_pattern\": \"How terms are defined when introduced\",\n    \"key_terms\": [\"List 8-12 domain-specific terms the site uses regularly\"]\n  },\n  \"formatting_conventions\": {\n    \"bold_usage\": \"When and how bold text is used\",\n    \"italic_usage\": \"When and how italics are used\",\n    \"link_style\": \"How links are presented\",\n    \"list_usage\": \"When lists are used vs prose\"\n  },\n  \"things_to_avoid\": [\n    \"Specific patterns the site clearly avoids — extract from what is NOT in the content\",\n    \"Include at least 8-10 items, each specific and observable\"\n  ],\n  \"things_to_emulate\": [\n    \"Specific patterns the site does well that should be preserved\",\n    \"Include at least 8-10 items, each specific and observable\"\n  ],\n  \"example_phrases\": {\n    \"characteristic\": [\n      \"Copy 5-8 short phrases from the content that are highly characteristic of the site's voice\",\n      \"A new writer should be able to read these and immediately grasp the tone\"\n    ],\n    \"would_never_say\": [\n      \"Write 5-8 phrases the site would NEVER use based on its established tone\"\n    ]\n  }\n}\n\nRules:\n- Extract patterns from the ACTUAL content provided — do not invent or assume\n- Be specific, not generic. 'Write clearly' is useless. 'Paragraphs are 2-3 sentences, leading with the conclusion' is actionable\n- The example_phrases.characteristic must be ACTUAL text copied from the provided content\n- The example_phrases.would_never_say should be invented counter-examples that clearly violate the observed style\n- If compliance patterns exist (financial disclaimers, medical caveats, legal language), capture them in detail\n- If no compliance patterns exist, return an empty compliance_rules array\n- writing_rules should have at least 10 entries\n- things_to_avoid and things_to_emulate should each have at least 8 entries\n- example_phrases.characteristic should have at least 5 entries\n- Every field in voice, sentence_style, persuasion_approach, and content_depth must be filled with specific observations, not generic writing advice"}, "next_step": "apply_plan", "error_step": "apply_plan", "description": "LLM extracts detailed writing style guide from representative content", "output_field": "content_direction_analysis"}, "extract_interactive_fingerprint": {"action": "extract_interactive_fingerprint", "config": {"crawl_field": "crawl_result"}, "next_step": "check_has_external_css", "description": "Extract interactive element signals (scripts, canvas, forms, library signatures) from crawled HTML — no LLM", "output_field": "interactive_fingerprint"}}, "start_step": "ensure_site_record"}, "ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "max_tokens": 16000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "processing_mode": "orchestrator", "timeout_seconds": 600}|t|2026-03-29 14:47:06.153658+00|2026-06-24 14:53:37.241209+00||[]|docker.io/aqls/agent-chassis|v1.0.1074||{"limits": {"cpu": "500m", "memory": "1Gi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}|{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}|{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 30}|[]|1|||||{"fallback_to_self": true, "prefer_delegation": true}||experimental|[]|{}|0|f|||0
e6ca8cca-398b-49f9-a435-337b1cc26c38|domain-research-classifier|Domain Research Classifier|Researches a domain via web search and scrape, classifies site type, extracts identity signals, writes findings to site_specs, creates next work item.|specialist|{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["analysis", "identity_written", "classification_written", "next_item_created"]}, "description": "Research and classification complete"}, "scrape_site": {"action": "scrape_web", "config": {"max_pages": 3, "url_field": "input_data.domain", "add_protocol": true, "extract_mode": "text", "follow_links": ["about", "services", "contact", "team", "pricing"]}, "next_step": "read_layout_taxonomy", "description": "Scrape the live site if it exists", "output_field": "scraped_data"}, "search_domain": {"action": "web_search", "config": {"num_results": 8, "query_template": "{{.input_data.domain}} website company"}, "next_step": "read_site_specs", "description": "Search for the domain to find its website and online presence", "output_field": "search_results"}, "read_site_specs": {"action": "read_site_spec", "config": {"site_id": "input_data.site_id"}, "next_step": "check_adoption_skip_scrape", "description": "Load site_specs (includes mission_brief and roadmap_brief if present)", "output_field": "site_specs"}, "create_next_item": {"action": "create_work_item", "config": {"source": "domain-research-classifier", "site_id": "input_data.site_id", "summary": "Domain strategy analysis needed after research", "priority": 8, "severity": "high", "item_type": "needs_strategy", "item_domain": "build", "handler_agent": "domain-strategist", "item_key_prefix": "strategy"}, "next_step": "complete", "description": "Create work item for domain strategy analysis", "output_field": "next_item_created"}, "write_identity_spec": {"action": "write_site_spec", "config": {"aspect": "identity", "source": "domain-research-classifier", "site_id": "input_data.site_id", "spec_data": "analysis.result.identity", "source_agent": "domain-research-classifier", "source_item_id": "input_data.work_item_id"}, "next_step": "write_classification_spec", "description": "Persist identity findings to site_specs", "output_field": "identity_written"}, "classify_and_extract": {"action": "execute_llm_prompt", "config": {"ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "max_tokens": 6000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["input_data", "search_results", "scraped_data", "site_specs"], "output_format": "json", "prompt_template": "You are analyzing a domain for website creation.\n\n## Build standard (applies to every site, regardless of inputs)\nAim for best-in-class quality in this site's field. The bar is not \"competent template\" but \"stands comparison with the strongest sites in this vertical\" — in the quality of the design, the clarity and usefulness of the writing, and the genuine value of any tools or content to the people who will actually use the site. When forming direction, consider what the best sites in this space do — how they position, what their design signals, how their copy reads, what earns return visits — and build on the reasoning behind those choices rather than copying them. Choose design and content that fit this specific industry and these objectives, not a generic house style. Favour fewer things done genuinely well over filler, and prefer interactive or visual elements where they aid understanding. Do what is most useful and interesting for the site's visitors.\n\nThis standard governs QUALITY and FIT, not scope. Do not invent services, pages, features, or facts beyond what the evidence supports; where research is thin, say so honestly in the confidence fields rather than fabricating detail. Treat aspirational ideas as direction to be realised at the pace the site's fidelity allows — adopted sites stay faithful to their source at first — not as things to force into the first build.\n\nDomain: {{.input_data.domain}}\nObjective: {{if .input_data.objective}}{{.input_data.objective}}{{else}}Not specified — infer from domain name and research{{end}}\n\n{{if .site_specs.specs.mission_brief}}## Pre-Defined Mission\nThis site has a strategic mission provided by the owner. Use this as STRONG guidance for identity, tone, positioning, and design direction. The research below validates and supplements — the mission is the primary source.\n\n{{.site_specs.specs.mission_brief.text}}\n{{end}}\n{{if .site_specs.specs.roadmap_brief}}## Roadmap\n{{.site_specs.specs.roadmap_brief.text}}\n{{end}}\n{{if .site_specs.specs.site_archetype}}## Adoption Reference — STRONGEST signal\n\nThis site has been adopted from {{if and .site_specs.specs.identity .site_specs.specs.identity.adopted_from}}{{.site_specs.specs.identity.adopted_from}}{{else}}an existing source{{end}}. The adoption agent crawled the source and captured what this site IS right now. The first deployed version should closely resemble the adopted source. Finder/fixer agents can widen any aspirational gap over time; your job in this run is to produce a spec that is faithful to the adopted state, with only the minimal extension needed to fill fields the adopted specs do not cover.\n\nTreat the following adopted specs as ground truth. Do NOT fabricate services, competitors, unique selling points, or positioning that contradict them. Do NOT rewrite design character that the adopted design_intent already describes.\n\n### Adopted identity\n{{.site_specs.specs.identity | toJSON}}\n\n### Adopted archetype (what kind of site this is)\n{{.site_specs.specs.site_archetype | toJSON}}\n{{if .site_specs.specs.content_direction}}\n### Adopted content direction (writing style)\n{{.site_specs.specs.content_direction | toJSON}}\n{{end}}{{if .site_specs.specs.design_intent}}\n### Adopted design intent (visual direction)\n{{.site_specs.specs.design_intent | toJSON}}\n{{end}}\n\n### Adoption fidelity guidance (follow precisely)\n- classification.site_type MUST be consistent with site_archetype.content.primary_type and site_archetype.label. A site archetyped as a tools/utility platform with primary content \"interactive tools and calculators\" is site_type \"tools\" or \"interactive-platform\" — NOT \"brochure\".\n- classification.tone_suggestion MUST be consistent with site_archetype.character.feel and the adopted content_direction voice.\n- classification.suggested_style MUST be consistent with the adopted design_intent — specifically the palette character and dark/light scheme. If the adopted design is dark, suggested_style must be a dark variant.\n- classification.category and classification.industry_tags MUST reflect the adopted archetype. For an adopted tools/utility platform: category=\"interactive\" and industry_tags include \"interactive-platform\" plus vertical tags drawn from site_archetype.industry (e.g. \"game-design\", \"developer-tools\"). For an adopted social/community platform: category=\"social\" and industry_tags include \"social-network\" plus specific modality tags the archetype describes (e.g. \"provocation-platform\", \"ai-seeded-community\"). Prefer tags that appear in the Current library tags list so the matcher can find a close layout rather than triggering a library-growth fallback.\n- identity.has_existing_site MUST be true — adoption evidence is present. identity.existing_site_quality should reflect site_archetype.character.polish.\n- identity.services — include ONLY what the adopted identity already contains or what site_archetype.purpose and content_model clearly imply. Do not invent services for a site whose archetype indicates no commercial services (e.g. revenue_model \"none\", content primarily tools or guides).\n- identity.competitors_found — leave empty unless the adopted identity already has competitors listed.\n- identity.unique_selling_points — derive from site_archetype.purpose and adopted content; do not invent.\n- content_direction — use the adopted content_direction as the baseline. Preserve its voice, writing_rules, things_to_avoid, and example_phrases. You may fill fields it does not populate, but do not substitute different wording for fields that do exist.\n- design_intent — preserve the adopted design_intent's palette reference values, typography, and dark/light scheme. You may refine guidance text or add character description, but do not propose different colours or a different scheme.\n- Preserve adopted_from and adopted_at in the identity output.\n{{end}}\nSearch Results:\n{{.search_results}}\n\nScraped Website Content:\n{{.scraped_data}}\n\nAnalyze everything and return a JSON object with FOUR sections. Be as specific and detailed as possible — vague guidance like \"professional tone\" is useless. Respond ONLY with valid JSON.\n\n1. \"identity\" — what we know about this entity:\n{\n  \"company_name\": \"Best guess at company/brand name\",\n  \"tagline\": \"Tagline if found, null otherwise\",\n  \"industry\": \"Primary industry/sector\",\n  \"sub_industry\": \"More specific classification\",\n  \"about_summary\": \"2-3 sentence summary of what this company does\",\n  \"services\": [{\"name\": \"Service 1\", \"description\": \"Brief desc\"}],\n  \"contact\": {\n    \"email\": \"if found\",\n    \"phone\": \"if found\",\n    \"address\": \"if found\",\n    \"location\": \"city/region if found\"\n  },\n  \"has_existing_site\": true,\n  \"existing_site_quality\": \"good/adequate/poor/none\",\n  \"social_profiles\": {\"linkedin\": \"url\", \"twitter\": \"url\"},\n  \"key_people\": [{\"name\": \"Name\", \"role\": \"Role\"}],\n  \"unique_selling_points\": [\"USP 1\", \"USP 2\"],\n  \"target_audience\": \"Description of likely target audience\",\n  \"competitors_found\": [\"competitor1.com\", \"competitor2.com\"]\n}\n\n2. \"classification\" — what kind of site to build:\n{\n  \"site_type\": \"brochure|landing|portfolio|content|ecommerce|tools|interactive-platform|social\",\n  \"category\": \"<pick one from the Current library categories listed below>\",\n  \"industry_tags\": [\"4 to 10 specific tags — see Current library tags below\"],\n  \"confidence\": 0.0-1.0,\n  \"reasoning\": \"Why this site type fits\",\n  \"recommended_builder\": \"pageflow-builder\",\n  \"page_count_estimate\": 5,\n  \"detected_signals\": [\"signal1\", \"signal2\"],\n  \"tone_suggestion\": \"professional|friendly|bold|technical|editorial|game-like|energetic\",\n  \"suggested_style\": \"professional-dark|modern-light|bold-creative|etc\"\n}\n\ncategory and industry_tags are used by the layout matcher (site-design-planner) to pick a CSS layout from the library. The matcher scores layouts by how many of these tags overlap with each layout's own industry_tags. Both fields must be populated.\n\n### category — the highest-level shape of the site. Pick ONE.\n\nCurrent library categories (read at this classifier run):\n{{.layout_taxonomy.categories | toJSON}}\n\nCategory meanings (stable vocabulary):\n- brochure — traditional marketing/company site (services, about, contact)\n- interactive — tool/utility platform, calculators, simulators, practitioner tools\n- social — community platform, forum, social network, AI-seeded discussion\n- editorial — news, magazine, blog, opinion, long-form content\n- ecommerce — storefront, product catalogue, checkout\n- portfolio — work showcase for a creative, studio, or individual\n- hub — vertical information hub, regulatory resource, trade directory (non-commercial)\n- docs — technical documentation, API reference, knowledge base\n\nIf the library has a category not documented above, it was added after this documentation was last updated. Prefer a documented meaning when one fits; fall back to a library-current category when none of the documented meanings match.\n\n### industry_tags — 4 to 10 specific tags describing this site. Include BOTH:\n- site-shape tags (e.g. \"interactive-platform\", \"tool-portal\", \"social-network\", \"provocation-platform\", \"magazine-grid\", \"affiliate-hub\", \"docs-sidebar\")\n- vertical/domain tags (e.g. \"game-design\", \"veterinary\", \"legal\", \"fitness\", \"fintech\", \"wellness\")\n\nUse hyphenated lowercase. Prefer specific over generic: \"game-design\" not \"games\", \"ai-platform\" not \"ai\".\n\nCurrent library tags (match these when they describe this site — each match is an overlap point for the matcher):\n{{.layout_taxonomy.industry_tags | toJSON}}\n\nThe library currently has {{.layout_taxonomy.layout_count}} active layouts. If no existing tag fits this site well, coin a new one using the same style — an unmatched tag will trigger a library-growth review work item rather than silently fail.\n\n3. \"content_direction\" — DETAILED writing style guide for all content on this site:\n{\n  \"voice\": {\n    \"register\": \"Describe the overall register this site should use — e.g. 'Down-to-earth and matter-of-fact, avoids sales language'\",\n    \"person\": \"Which grammatical person — e.g. 'Second person (you/your) for the reader, first plural (we) for the company'\",\n    \"authority_level\": \"How the site should establish authority — e.g. 'States expertise confidently but never promises specific outcomes'\",\n    \"emotional_tone\": \"The emotional quality — e.g. 'Reassuring without being patronising'\",\n    \"formality\": \"Where on the formal-casual spectrum — e.g. 'Professional but not stiff. Uses contractions.'\"\n  },\n  \"sentence_style\": {\n    \"average_length\": \"Short/medium/long for this industry\",\n    \"structure_patterns\": \"How sentences should be constructed\",\n    \"rhythm\": \"The cadence appropriate for this audience\"\n  },\n  \"persuasion_approach\": {\n    \"method\": \"How the site should convince without hard selling\",\n    \"trust_building\": \"How trust should be established for this industry\",\n    \"social_proof_style\": \"How to handle testimonials and social proof\"\n  },\n  \"content_depth\": {\n    \"thoroughness\": \"How deeply topics should be explored\",\n    \"assumed_knowledge\": \"What the target audience already knows\",\n    \"explanation_pattern\": \"How complex ideas should be introduced\"\n  },\n  \"writing_rules\": [\n    \"At least 8 specific, actionable rules appropriate for this industry\",\n    \"Example for finance: 'Never promise specific returns or savings'\",\n    \"Example for health: 'Always recommend consulting a professional'\",\n    \"Example for tech: 'Explain jargon on first use'\"\n  ],\n  \"compliance_rules\": [\n    \"Industry-specific legal/regulatory rules — empty array if none apply\",\n    \"Example for finance: 'Calculations are illustrative — do not constitute financial advice'\",\n    \"Example for health: 'Information is not a substitute for professional medical advice'\"\n  ],\n  \"heading_style\": {\n    \"format\": \"How headings should be phrased for this industry\",\n    \"hierarchy\": \"How heading levels should be used\"\n  },\n  \"paragraph_style\": {\n    \"typical_length\": \"Appropriate paragraph length for the audience\",\n    \"structure\": \"How paragraphs should be organised\"\n  },\n  \"cta_style\": {\n    \"approach\": \"How calls-to-action should be handled\",\n    \"verb_choices\": \"What action verbs are appropriate\"\n  },\n  \"terminology\": {\n    \"approach\": \"How domain-specific terms should be handled\",\n    \"key_terms\": [\"List 5-10 key terms for this industry that content will need\"]\n  },\n  \"things_to_avoid\": [\n    \"At least 6 specific things to avoid for this industry\",\n    \"Example: 'Urgency language (limited time, act now)'\",\n    \"Example: 'Unsubstantiated claims about results'\"\n  ],\n  \"things_to_emulate\": [\n    \"At least 6 positive patterns appropriate for this industry\",\n    \"Example: 'Lead with the user benefit, not the feature'\"\n  ],\n  \"example_phrases\": {\n    \"characteristic\": [\"3-5 example phrases showing the right tone for this site\"],\n    \"would_never_say\": [\"3-5 phrases this site should never use\"]\n  }\n}\n\n4. \"design_intent\" — visual direction:\n{\n  \"style_direction\": \"professional-dark|modern-light|bold-creative\",\n  \"colour_mood\": \"Description of colour feeling and why\",\n  \"typography_mood\": \"Font personality description\",\n  \"imagery_direction\": \"What images should convey\",\n  \"layout_preference\": \"Layout style\",\n  \"avoid\": [\"Design elements to avoid\"],\n  \"palette\": {\n    \"reference_values\": {\n      \"primary\": \"Hex for the dominant brand colour (not the accent)\",\n      \"secondary\": \"Hex for a supporting colour\",\n      \"accent\": \"Hex for the single emphasis colour (CTAs, highlights)\",\n      \"background\": \"Hex for the page background\",\n      \"surface\": \"Hex for card/panel backgrounds\",\n      \"text\": \"Hex for body text\",\n      \"text_muted\": \"Hex for secondary/muted text\",\n      \"border\": \"Hex for hairlines/dividers\"\n    }\n  },\n  \"typography\": {\n    \"reference_values\": {\n      \"font_family\": \"Body font stack, e.g. 'IBM Plex Sans', system-ui, sans-serif\",\n      \"heading_font\": \"Heading font stack, e.g. 'Fraunces', Georgia, serif\"\n    }\n  }\n}\n\nIMPORTANT:\n- If adoption reference is provided above, the Adoption fidelity guidance is MANDATORY. Adoption evidence outranks mission_brief, search_results, and scraped_data for identity, content_direction, and design_intent. Follow the fidelity rules precisely — this is the user's captured existing site, not a blank slate.\n- If a mission is provided above (and no adoption), derive identity/tone/design from it. Research validates.\n- If no mission and no adoption, infer everything from domain name, research, and objective.\n- If no existing site found and no adoption, infer from the domain name and industry norms.\n- Be specific about industry — \"veterinary practice\" not just \"healthcare\".\n- content_direction.writing_rules must have at least 8 entries.\n- content_direction.things_to_avoid and things_to_emulate must each have at least 6 entries.\n- content_direction.compliance_rules should be populated for regulated industries (finance, health, legal, insurance) and empty [] for others.\n- Every field in content_direction must be specific to THIS industry, not generic writing advice.\n- For interactive-platform or novel site types, use those in site_type rather than forcing brochure.\n- recommended_builder should always be \"pageflow-builder\" for now.\n- design_intent.palette.reference_values (all eight slots, as hex) and design_intent.typography.reference_values (font_family and heading_font, as CSS font stacks) are MANDATORY: the composition pipeline (site-design-planner) and the design renderer read these structured fields, not the prose colour_mood/typography_mood. Populate every slot. Map the dominant brand colour to primary and the single emphasis colour to accent (they are usually different). Never default to generic blue-and-grey; derive the palette from the mission/adoption/research and the industry. style_direction must agree with the palette you emit (a light palette is not \"professional-dark\").\n\nReturn ONLY valid JSON with identity, classification, content_direction, and design_intent keys.\n"}, "next_step": "write_identity_spec", "description": "LLM classifies site and extracts identity from research", "output_field": "analysis"}, "read_layout_taxonomy": {"action": "read_layout_taxonomy", "config": {}, "next_step": "classify_and_extract", "description": "Load current categories and industry_tags from the layouts library so the prompt renders with the live taxonomy", "output_field": "layout_taxonomy"}, "write_design_intent_spec": {"action": "write_site_spec", "config": {"aspect": "design_intent", "source": "domain-research-classifier", "site_id": "input_data.site_id", "spec_data": "analysis.result.design_intent", "error_step": "create_next_item", "source_agent": "domain-research-classifier", "source_item_id": "input_data.work_item_id"}, "next_step": "create_next_item", "description": "Persist design intent to site_specs", "output_field": "design_intent_written"}, "write_classification_spec": {"action": "write_site_spec", "config": {"aspect": "classification", "source": "domain-research-classifier", "site_id": "input_data.site_id", "spec_data": "analysis.result.classification", "source_agent": "domain-research-classifier", "source_item_id": "input_data.work_item_id"}, "next_step": "write_content_direction_spec", "description": "Persist classification to site_specs", "output_field": "classification_written"}, "check_adoption_skip_scrape": {"action": "conditional", "config": {"condition": "site_specs.specs.site_archetype != null", "else_step": "scrape_site", "then_step": "read_layout_taxonomy"}, "description": "For adopted sites (site_archetype present), skip scrape_site — adoption specs already carry the content knowledge. For blank-domain builds, proceed to scrape."}, "write_content_direction_spec": {"action": "write_site_spec", "config": {"aspect": "content_direction", "source": "domain-research-classifier", "site_id": "input_data.site_id", "spec_data": "analysis.result.content_direction", "error_step": "create_next_item", "source_agent": "domain-research-classifier", "source_item_id": "input_data.work_item_id"}, "next_step": "write_design_intent_spec", "description": "Persist content direction to site_specs", "output_field": "content_direction_written"}}, "start_step": "search_domain"}, "processing_mode": "orchestrator", "timeout_seconds": 180}|t|2026-02-24 16:07:35.422594+00|2026-06-24 14:53:37.241209+00||["web-search", "scraping", "classification", "llm"]|docker.io/aqls/agent-chassis|v1.0.1074||{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}|{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}|{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}|[]|1|||||{"fallback_to_self": true, "prefer_delegation": true}|analyst|experimental|["domain-research", "classification", "identity-extraction"]|{}|0|f|{"optional": ["objective", "work_item_id"], "required": ["site_id", "domain"], "description": "Receives site_id + domain from dispatch loop. Optional objective from build_queue direction."}|{"produces": {"identity_written": "site_spec write result for identity aspect", "next_item_created": "work item created for next pipeline stage", "classification_written": "site_spec write result for classification aspect"}}|0
099b51e0-6dd0-4856-8f82-805a379e8b1d|build-dispatch-loop|Build Dispatch Loop|Processes one work item per invocation, then spawns itself if more remain. No loops or sub_workflows — each dispatch is a separate orchestration with clean logs.|orchestrator|{"workflow": {"steps": {"complete": {"action": "complete_workflow", "config": {"output_fields": ["pending"]}, "description": "Dispatch complete — trigger will invoke again if more items remain"}, "load_items": {"action": "load_work_items", "config": {"site_id": "input_data.site_id", "max_items": 5}, "next_step": "check_has_items", "description": "Load one dispatchable item", "output_field": "pending"}, "process_item": {"action": "loop", "config": {"items_field": "pending.items", "sub_workflow": {"steps": {"done": {"action": "loop_complete", "description": "Item done"}, "claim": {"action": "claim_work_item", "config": {"work_item_id": "current_item.id"}, "next_step": "check_claim", "description": "Atomically claim item", "output_field": "claim_result"}, "check_claim": {"action": "conditional", "config": {"condition": "claim_result.claimed == true", "else_step": "done", "then_step": "spawn_handler"}, "description": "Skip if already claimed by another instance"}, "mark_failed": {"action": "fail_work_item", "config": {"work_item_id": "current_item.id", "error_message": "Handler failed"}, "next_step": "done", "description": "Mark item failed, continue", "output_field": "item_failed"}, "call_handler": {"action": "call_agent", "config": {"error_step": "mark_failed", "target_role": "handler", "input_mapping": {"spec": "current_item.spec", "domain": "input_data.domain", "issue?": "current_item.spec.issue", "source": "current_item.source", "site_id": "current_item.site_id", "item_type": "current_item.item_type", "page_name?": "current_item.spec.page_name", "current_page": "current_item.spec", "work_item_id": "current_item.id", "component_id?": "current_item.spec.component_id", "reviewed_brief?": "current_item.spec.reviewed_brief"}, "timeout_seconds": 1200}, "next_step": "mark_complete", "description": "Call handler agent", "output_field": "handler_result"}, "mark_complete": {"action": "complete_work_item", "config": {"result": "handler_result", "work_item_id": "current_item.id"}, "next_step": "done", "description": "Mark item complete", "output_field": "item_completed"}, "spawn_handler": {"action": "spawn_agent", "config": {"role": "handler", "error_step": "mark_failed", "agent_type_field": "current_item.handler_agent"}, "next_step": "call_handler", "description": "Spawn handler (dynamic type per item)", "output_field": "handler_spawned"}}, "start_step": "claim"}, "item_variable": "current_item", "max_iterations": 5, "continue_on_error": false}, "next_step": "complete", "description": "Process single item: claim, spawn, call, mark"}, "check_has_items": {"action": "conditional", "config": {"condition": "pending.has_items == true", "else_step": "notify_scheduler", "then_step": "process_item"}, "description": "Any items to process?"}, "notify_scheduler": {"action": "query_database", "config": {"query": "UPDATE scheduled_tasks SET last_completed_at = NOW() WHERE name = 'build-pipeline-trigger'", "output_format": "object"}, "next_step": "complete", "description": "Tell scheduler this execution finished so it can fire again", "output_field": "scheduler_notified"}}, "start_step": "load_items", "processing_mode": "orchestrator", "timeout_seconds": 4200}}|t|2026-02-24 16:56:54.875139+00|2026-06-24 14:53:37.241209+00||["dispatch", "orchestration", "work-items"]|docker.io/aqls/agent-chassis|v1.0.1074||{"limits": {"cpu": "500m", "memory": "512Mi"}, "requests": {"cpu": "100m", "memory": "256Mi"}}|{"error": "system.errors.{type}", "process": "system.agent.{type}.process", "response": "system.responses.{type}"}|{"port": 8080, "liveness_path": "/health", "readiness_path": "/ready", "initial_delay_seconds": 15}|[]|1|||||{"fallback_to_self": true, "prefer_delegation": true}|coordinator|experimental|["build", "dispatch", "orchestration"]|{}|0|f|{"optional": ["domain"], "required": ["site_id"], "description": "Receives site_id from seed_build_queue or external trigger."}|{"produces": {"item_failed": "Work item marked failed (if error_step triggered)", "handler_result": "Result from the handler agent", "item_completed": "Work item marked complete", "next_dispatch_result": "Result from chained dispatch (if any)"}}|600
