        <span class="stat-icon" aria-hidden="true"></span>
        <strong class="stat-value" data-animate data-target=""><span class="stat-number"></span><span class="stat-suffix"></span></strong>
        <span class="stat-label"></span>
        <span class="stat-description"></span>
      </li>
    </ul>

    <p class="stats-footnote"></p>
  </div>
</section>

<script>
(function() {
  var section = document.querySelector('[data-component="system-stats"]');
  if (!section) return;

  function animateCount(el, target, duration) {
    var start = 0;
    var startTime = null;
    var isFloat = target % 1 !== 0;

    function step(timestamp) {
      if (!startTime) startTime = timestamp;
      var progress = Math.min((timestamp - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3);
      var current = eased * target;
      el.textContent = isFloat ? current.toFixed(1) : Math.floor(current).toLocaleString();
      if (progress < 1) {
        requestAnimationFrame(step);
      } else {
        el.textContent = isFloat ? target.toFixed(1) : target.toLocaleString();
      }
    }
    requestAnimationFrame(step);
  }

  var observed = false;
  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if (entry.isIntersecting && !observed) {
        observed = true;
        var cards = section.querySelectorAll('[data-animate][data-target]');
        cards.forEach(function(card) {
          var target = parseFloat(card.getAttribute('data-target'));
          var numberEl = card.querySelector('.stat-number');
          if (!isNaN(target) && numberEl) {
            animateCount(numberEl, target, 1800);
          }
        });
        observer.disconnect();
      }
    });
  }, { threshold: 0.2 });

  observer.observe(section);
})();
</script>
